'use strict';
const POLOS=['PIB Batel','Centro de Formação Batel','PIB Uberaba','PIB Boqueirão','PIB Piraquara','PIB Colombo','PIB Tamandaré','PIB Campo Largo','PIB Campo Comprido','Chácara Masculina','Chácara Feminina','Cristolândia Mandirituba','Cristolândia Portão','Jonnys House','PIB Portão'];
const CHECK=['Rotas de fuga verificadas','Extintores no lugar e dentro da validade','Iluminação de emergência funcionando','Saídas desobstruídas','Kit de primeiros socorros / DEA conferido','Comunicação por rádio testada'];
const TIPOS=['Atendimento médico / primeiros socorros','Princípio de incêndio','Conflito / perturbação','Criança perdida','Outro'];
const PLU={bc:'Bombeiros civis',seg:'Seguranças descaracterizados',bri:'Brigadistas profissionais'};
const FUN={bc:'Bombeiro civil',seg:'Segurança descaracterizado',bri:'Brigadista profissional'};
const DIAS=['domingo','segunda','terça','quarta','quinta','sexta','sábado'];
const MESES=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const RESP='Antônio Neto e Equipe Operacional';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defModelo=()=>[{dia:5,hora:'19:30',nome:'Sexta noite'},{dia:6,hora:'19:30',nome:'Sábado noite'},{dia:0,hora:'10:00',nome:'Domingo manhã'},{dia:0,hora:'18:00',nome:'Domingo noite'}];
const VER='v7';const CFGK='bc-cultos-cfg';
// a chave 'cfg' é compartilhada com o app de Manutenção dos Polos (mesmo domínio github.io): só aproveita se for deste app
function normCfg(c){c=(c&&typeof c==='object')?c:{};if(!Array.isArray(c.modelo)||!c.modelo.every(t=>t&&typeof t.dia==='number'))c.modelo=defModelo();c.modelo=c.modelo.map(t=>({dia:t.dia,hora:t.hora||'19:30',nome:t.nome||'Culto'}));if(typeof c.polo!=='string'||!c.polo)c.polo='PIB Batel';if(!/^\d{4}-\d{2}$/.test(c.inicio||''))c.inicio=ymd(new Date()).slice(0,7);return{modelo:c.modelo,polo:c.polo,inicio:c.inicio}}
let cfg=(()=>{let c=null;try{c=JSON.parse(localStorage.getItem(CFGK)||'null')}catch(e){}if(!c){try{const o=JSON.parse(localStorage.getItem('cfg')||'null');if(o&&Array.isArray(o.modelo))c=o}catch(e){}}return normCfg(c)})();
function saveCfg(){cfg=normCfg(cfg);localStorage.setItem(CFGK,JSON.stringify(cfg))}saveCfg();
function ymd(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
const pd=s=>{const[a,b,c]=s.split('-').map(Number);return new Date(a,b-1,c||1)};
const fmt=s=>{const d=pd(s);return d.toLocaleDateString('pt-BR')+' ('+DIAS[d.getDay()]+')'};
const mesNome=m=>{const d=pd(m);return MESES[d.getMonth()]+' de '+d.getFullYear()};
const addMes=(m,n)=>{const d=pd(m);d.setMonth(d.getMonth()+n);return ymd(d).slice(0,7)};
const mesAtual=()=>ymd(new Date()).slice(0,7);
const mesesPiloto=()=>[0,1,2].map(i=>addMes(cfg.inicio,i));
const min=t=>{if(!t)return null;const[h,m]=t.split(':').map(Number);return h*60+m};
const horas=c=>{const a=min(c.checkin||(c.kind==='diaria'?c.hora:'')),b=min(c.checkout||(c.kind==='diaria'?c.horaFim:''));if(a==null||b==null)return 0;let d=b-a;if(d<0)d+=1440;return d/60};
const hfmt=h=>h.toFixed(1).replace('.',',')+' h';
// ---------- IndexedDB ----------
let dbp;function db(){return dbp||(dbp=new Promise((ok,er)=>{const r=indexedDB.open('bc-cultos',2);r.onupgradeneeded=()=>{for(const s of['equipe','cultos','midias','viaturas'])if(!r.result.objectStoreNames.contains(s))r.result.createObjectStore(s,{keyPath:'id'})};r.onsuccess=()=>ok(r.result);r.onerror=()=>er(r.error)}))}
async function tx(st,mode,fn){const d=await db();return new Promise((ok,er)=>{const t=d.transaction(st,mode);const r=fn(t.objectStore(st));t.oncomplete=()=>ok(r&&r.result);t.onerror=()=>er(t.error)})}
const arr=x=>Array.isArray(x)?x:[];
function normOc(o){o=o||{};return{tipo:o.tipo||'Outro',hora:o.hora||'',desc:o.desc||'',acao:o.acao||'',enc:o.enc||'',midias:arr(o.midias)}}
const NORM={cultos:c=>{if(!c)return c;c.data=c.data||'2000-01-01';c.hora=c.hora||'';c.nome=c.nome||'Culto';c.polo=c.polo||'PIB Batel';const b=arr(c.bc);c.bc=[b[0]||'',b[1]||''];c.seg=c.seg||'';c.bri=arr(c.bri);c.check=(c.check&&typeof c.check==='object')?c.check:{};c.ocorrencias=arr(c.ocorrencias).map(normOc);c.midias=arr(c.midias);c.obs=c.obs||'';c.checkin=c.checkin||'';c.checkout=c.checkout||'';c.amb=!!c.amb;c.viatura=c.viatura||'';return c},
equipe:p=>p&&Object.assign({funcao:'bc',tel:'',cert:'',validade:''},p,{nome:p.nome||'(sem nome)'}),viaturas:v=>v&&Object.assign({placa:'',tipo:'Ambulância de apoio',condutor:'',obs:''},v,{nome:v.nome||'(sem nome)'})};
const nrm=(st,v)=>NORM[st]?NORM[st](v):v;
const getAll=st=>tx(st,'readonly',s=>s.getAll()).then(l=>arr(l).filter(Boolean).map(v=>nrm(st,v)));const get=(st,k)=>tx(st,'readonly',s=>s.get(k)).then(v=>nrm(st,v));const put=(st,v)=>tx(st,'readwrite',s=>s.put(v));const del=(st,k)=>tx(st,'readwrite',s=>s.delete(k));
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
// ---------- mídia ----------
function comprimir(file){return new Promise(ok=>{const img=new Image();img.onload=()=>{const m=1280,s=Math.min(1,m/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=img.width*s;c.height=img.height*s;c.getContext('2d').drawImage(img,0,0,c.width,c.height);c.toBlob(b=>ok(b),'image/jpeg',.72);URL.revokeObjectURL(img.src)};img.onerror=()=>ok(file);img.src=URL.createObjectURL(file)})}
const toDataURL=b=>new Promise(ok=>{const r=new FileReader();r.onload=()=>ok(r.result);r.readAsDataURL(b)});
async function thumbs(ids){let h='';for(const id of ids||[]){const m=await get('midias',id);if(!m)continue;const u=URL.createObjectURL(m.blob);h+=m.tipo.startsWith('video')?`<video src="${u}" controls></video>`:`<img src="${u}">`}return h}
// ---------- dados ----------
async function equipe(){return(await getAll('equipe')).sort((a,b)=>a.nome.localeCompare(b.nome))}
async function viaturas(){return(await getAll('viaturas')).sort((a,b)=>a.nome.localeCompare(b.nome))}
const mapV=async()=>Object.fromEntries((await viaturas()).map(v=>[v.id,v]));
const vNome=(V,id)=>V[id]?V[id].nome+(V[id].placa?' ('+V[id].placa+')':''):'viatura não definida';
async function diariasMes(m){return(await getAll('cultos')).filter(c=>c.kind==='diaria'&&c.data.startsWith(m)).sort((a,b)=>(a.data+a.hora)<(b.data+b.hora)?-1:1)}
async function cultosMes(m){return(await getAll('cultos')).filter(c=>c.kind!=='diaria'&&c.data.startsWith(m)).sort((a,b)=>(a.data+a.hora)<(b.data+b.hora)?-1:1)}
function novoCulto(data,hora,nome,polo){return{id:uid(),data,hora,nome:nome||'Culto',polo:polo||cfg.polo,bc:['',''],seg:'',bri:[],checkin:'',checkout:'',check:{},publico:'',ocorrencias:[],midias:[],obs:'',concluido:false}}
function datasModelo(m){const r=[];const d=pd(m+'-01');const mm=d.getMonth();while(d.getMonth()===mm){for(const t of cfg.modelo)if(t.dia===d.getDay())r.push({data:ymd(d),...t});d.setDate(d.getDate()+1)}return r}
const porSemana=()=>cfg.modelo.length;const porMes=()=>porSemana()*4;
const completo=c=>c.bc[0]&&c.bc[1]&&c.seg&&c.bc[0]!==c.bc[1]&&(c.bri||[]).every(Boolean);
function faltas(c){const f=[];const n=c.bc.filter(Boolean).length;if(n<2)f.push((2-n)+' bombeiro(s) civil(is)');if(c.bc[0]&&c.bc[0]===c.bc[1])f.push('bombeiro repetido');if(!c.seg)f.push('segurança');const nb=(c.bri||[]).filter(x=>!x).length;if(nb)f.push(nb+' brigadista(s) não selecionado(s)');return f}
const status=c=>c.concluido?['concluida','Atendido']:completo(c)?['pendente','Escalado']:['atrasada','Escala incompleta'];
function validade(p){if(!p.validade)return'';const d=(pd(p.validade)-new Date())/864e5;return d<0?'<span class="st atrasada">Certificado vencido</span>':d<60?'<span class="st pendente">Vence em breve</span>':''}
// ---------- rotas ----------
const R={};window.addEventListener('hashchange',go);
async function go(){const[h,...a]=(location.hash.slice(1)||'painel').split('/');document.querySelectorAll('nav a').forEach(x=>x.classList.toggle('on',x.getAttribute('href')==='#'+h));window.scrollTo(0,0);try{await(R[h]||R.painel)(...a.map(decodeURIComponent))}catch(e){console.error(e);$('#app').innerHTML='<div class="card"><b>Erro ao abrir a tela.</b><p class="muted">'+esc(e.message)+'</p><button class="btn" onclick="location.reload()">Recarregar</button><button class="btn out" onclick="forcarAtualizacao()">🔄 Forçar atualização</button><p class="muted">Versão '+VER+'. Seus dados (cultos, equipe, fotos) não são apagados.</p></div>'}}
R.painel=async()=>{const m=mesAtual();const cs=await cultosMes(m);const eq=await equipe();const E=Object.fromEntries(eq.map(p=>[p.id,p]));
const at=cs.filter(c=>c.concluido),oc=cs.reduce((s,c)=>s+c.ocorrencias.length,0),inc=cs.filter(c=>!completo(c)).length,hs=at.reduce((s,c)=>s+horas(c),0);
const hoje=ymd(new Date());const prox=cs.filter(c=>c.data>=hoje&&!c.concluido).slice(0,6);
$('#app').innerHTML=`<h2>Painel – ${mesNome(m)}</h2><div class="grid"><div class="card kpi"><b>${at.length}/${cs.length}</b><small>cultos atendidos</small></div><div class="card kpi"><b>${hfmt(hs)}</b><small>horas de serviço</small></div><div class="card kpi"><b style="color:var(--red)">${oc}</b><small>ocorrências</small></div><div class="card kpi"><b style="color:${inc?'var(--red)':'var(--ok)'}">${inc}</b><small>escalas incompletas</small></div></div>
<p class="muted">Cada culto: 2 bombeiros civis + 1 segurança descaracterizado + brigadistas profissionais conforme necessidade · Equipe cadastrada: ${eq.filter(p=>p.funcao==='bc').length} BC, ${eq.filter(p=>p.funcao==='seg').length} seg., ${eq.filter(p=>p.funcao==='bri').length} brigadista(s)</p>
<h3>Próximos cultos</h3>${prox.length?prox.map(c=>cardCulto(c,E)).join(''):`<div class="card muted">Nenhum culto escalado. Vá em <a href="#escala">Escala</a> e gere os cultos do mês.</div>`}`};
function cardCulto(c,E){const[s,t]=status(c);const nm=id=>E[id]?esc(E[id].nome):'—';return`<a class="card" style="display:block;text-decoration:none;color:inherit" href="#culto/${c.id}"><div class="polo"><div><b>${esc(c.nome)} – ${fmt(c.data)} ${c.hora}</b><div class="muted">${esc(c.polo)}<br>BC: ${nm(c.bc[0])}, ${nm(c.bc[1])} · Seg.: ${nm(c.seg)}${(c.bri||[]).length?' · Brig.: '+c.bri.map(nm).join(', '):''}${c.amb?' · 🚑 Ambulância de apoio':''}${c.ocorrencias.length?' · Ocorrências: <b style="color:var(--red)">'+c.ocorrencias.length+'</b>':''}</div></div><span class="st ${s}">${t}</span></div></a>`}
// ---------- equipe ----------
R.equipe=async(id)=>{const eq=await equipe();const p=eq.find(x=>x.id===id)||{id:'',nome:'',funcao:'bc',tel:'',cert:'',validade:''};
$('#app').innerHTML=`<h2>Equipe</h2><a class="btn gold" href="#viaturas">🚑 Viaturas (Ambulância de apoio)</a><div class="card"><b>${p.id?'Editar profissional':'Novo profissional'}</b><br><label>Nome</label><input id="pNome" value="${esc(p.nome)}"><label>Função</label><select id="pFun">${Object.entries(FUN).map(([k,v])=>`<option value="${k}" ${p.funcao===k?'selected':''}>${v}</option>`).join('')}</select><label>Telefone</label><input id="pTel" type="tel" value="${esc(p.tel)}"><label>Nº do certificado / registro</label><input id="pCert" value="${esc(p.cert)}"><label>Validade do certificado</label><input id="pVal" type="date" value="${esc(p.validade)}"><button class="btn" onclick="salvarPro('${p.id}')">Salvar profissional</button>${p.id?`<button class="btn out" onclick="if(confirm('Remover este profissional?')){del('equipe','${p.id}').then(()=>location.hash='#equipe')}">Remover</button>`:''}</div>
${['bc','seg','bri'].map(f=>`<h3>${PLU[f]} (${eq.filter(x=>x.funcao===f).length})</h3>`+eq.filter(x=>x.funcao===f).map(x=>`<a class="card polo" style="text-decoration:none;color:inherit" href="#equipe/${x.id}"><div><b>${esc(x.nome)}</b><div class="muted">${esc(x.tel)||'—'} · Reg.: ${esc(x.cert)||'—'} · Validade: ${x.validade?pd(x.validade).toLocaleDateString('pt-BR'):'—'}</div></div>${validade(x)}</a>`).join('')).join('')}`};
window.salvarPro=async id=>{const nome=$('#pNome').value.trim();if(!nome)return alert('Informe o nome.');await put('equipe',{id:id||uid(),nome,funcao:$('#pFun').value,tel:$('#pTel').value,cert:$('#pCert').value,validade:$('#pVal').value});location.hash='#equipe';go()};
// ---------- escala ----------
R.escala=async(m)=>{m=m||mesAtual();const cs=await cultosMes(m);const eq=await equipe();const bcs=eq.filter(p=>p.funcao==='bc'),sgs=eq.filter(p=>p.funcao==='seg'),brs=eq.filter(p=>p.funcao==='bri');const vts=await viaturas();const opV=v=>'<option value="">— selecione a viatura —</option>'+vts.map(x=>`<option value="${x.id}" ${x.id===v?'selected':''}>${esc(x.nome)}${x.placa?' – '+esc(x.placa):''}</option>`).join('');
const op=(l,v)=>'<option value="">— selecione —</option>'+l.map(p=>`<option value="${p.id}" ${p.id===v?'selected':''}>${esc(p.nome)}</option>`).join('');
const polos=v=>POLOS.map(p=>`<option ${p===v?'selected':''}>${p}</option>`).join('')+(POLOS.includes(v)?'':`<option selected>${esc(v)}</option>`);
const rows=cs.map(c=>{const f=faltas(c);const[s,t]=status(c);return`<div class="card"${c.avulso?' style="border-left:6px solid var(--gold)"':''}>${c.avulso?'<span class="ex">⭐ EVENTO AVULSO</span>':''}<div class="polo"><b>${esc(c.nome)} – ${fmt(c.data)} ${c.hora}</b><span class="st ${s}">${t}</span></div>
<div class="row2"><input type="date" value="${c.data}" onchange="setC('${c.id}','data',this.value)"><input type="time" value="${c.hora}" onchange="setC('${c.id}','hora',this.value)"></div>
<label class="muted">Polo / local</label><input list="lpolos" value="${esc(c.polo)}" onchange="setC('${c.id}','polo',this.value)">
<label class="muted">Bombeiro civil 1</label><select onchange="setBC('${c.id}',0,this.value)">${op(bcs,c.bc[0])}</select><label class="muted">Bombeiro civil 2</label><select onchange="setBC('${c.id}',1,this.value)">${op(bcs,c.bc[1])}</select><label class="muted">Segurança descaracterizado</label><select onchange="setC('${c.id}','seg',this.value)">${op(sgs,c.seg)}</select><label class="muted">Brigadistas profissionais (opcional)</label><select onchange="setNB('${c.id}',+this.value)">${[0,1,2,3,4,5,6].map(n=>`<option value="${n}" ${(c.bri||[]).length===n?'selected':''}>${n} brigadista(s)</option>`).join('')}</select>${(c.bri||[]).map((v,j)=>`<label class="muted">Brigadista profissional ${j+1}</label><select onchange="setBR('${c.id}',${j},this.value)">${op(brs,v)}</select>`).join('')}<label class="chk"><input type="checkbox" ${c.amb?'checked':''} onchange="setC('${c.id}','amb',this.checked)">🚑 Ambulância de apoio (opcional)</label>${c.amb?`<select onchange="setC('${c.id}','viatura',this.value)">${opV(c.viatura)}</select>${vts.length?'':'<div class="muted">Cadastre a viatura em Equipe › Viaturas.</div>'}`:''}${f.length?`<div class="warn">⚠ Escala incompleta: falta ${f.join(', ')}</div>`:`<div class="okb">✔ Escala completa (2 BC + 1 segurança${(c.bri||[]).length?' + '+c.bri.length+' brigadista(s)':''})</div>`}
<a class="btn sec" href="#culto/${c.id}">${c.concluido?'Ver registro':'Abrir registro do culto'}</a><button class="btn out" onclick="if(confirm('Excluir este culto?')){del('cultos','${c.id}').then(go)}">Excluir culto</button></div>`}).join('');
$('#app').innerHTML=`<h2>Escala</h2><a class="btn gold" href="#diarias/${m}">🚑 Diárias de ambulância</a><datalist id="lpolos">${POLOS.map(p=>`<option value="${p}">`).join('')}</datalist><div class="grid">${m>mesAtual()?`<a class="btn out" href="#escala/${addMes(m,-1)}">◀ Anterior</a>`:'<span></span>'}${m<LIM.slice(0,7)?`<a class="btn out" href="#escala/${addMes(m,1)}">Próximo ▶</a>`:'<span></span>'}</div><h3>${mesNome(m)} – ${cs.length} culto(s)</h3>
${eq.length?'':'<div class="warn">Cadastre a equipe primeiro na aba Equipe.</div>'}
<button class="btn" onclick="gerarMes('${m}')">➕ Gerar cultos do mês pelo modelo semanal</button>
${calHTML(m,cs)}<button class="btn sec" onclick="gerarAte()">📆 Gerar cultos até 30/01/2027</button><div class="card" id="fAvulso"><b>⭐ Evento avulso</b><p class="muted">Toque em uma data do calendário ou preencha abaixo.</p><div class="row2"><input type="date" id="nData" value="${m}-01"><input type="time" id="nHora" value="19:30"></div><input id="nNome" placeholder="Nome do evento (ex.: Conferência, culto especial)"><input list="lpolos" id="nPolo" value="${esc(cfg.polo)}" placeholder="Polo ou local (texto livre)"><label class="chk"><input type="checkbox" id="nAmb">🚑 Ambulância de apoio</label><p class="muted">A equipe (bombeiros, segurança, brigadistas) é escolhida no card do evento, abaixo, depois de adicionar.</p><button class="btn gold" onclick="avulso()">Adicionar evento avulso</button></div>${rows}
<h3>Modelo semanal (editável)</h3><div class="card">${cfg.modelo.map((t,i)=>`<div class="row2"><input value="${esc(t.nome)}" onchange="cfg.modelo[${i}].nome=this.value;saveCfg()"><select onchange="cfg.modelo[${i}].dia=+this.value;saveCfg()">${[5,6,0,1,2,3,4].map(n=>`<option value="${n}" ${t.dia===n?'selected':''}>${DIAS[n]}</option>`).join('')}</select></div><div class="row2"><input type="time" value="${t.hora}" onchange="cfg.modelo[${i}].hora=this.value;saveCfg()"><button class="btn out" style="margin:4px 0 8px;padding:10px" onclick="cfg.modelo.splice(${i},1);saveCfg();go()">Remover</button></div>`).join('')}
<button class="btn out" onclick="cfg.modelo.push({dia:0,hora:'19:00',nome:'Novo culto'});saveCfg();go()">+ Adicionar horário</button><label class="muted">Polo padrão</label><select onchange="cfg.polo=this.value;saveCfg()">${polos(cfg.polo)}</select><button class="btn out" onclick="if(confirm('Voltar ao modelo padrão?')){cfg.modelo=defModelo();saveCfg();go()}">Restaurar padrão (sex noite, sáb noite, dom manhã, dom noite)</button></div>`};
window.gerarMes=async m=>{const cs=await cultosMes(m);let n=0;for(const t of datasModelo(m)){if(cs.some(c=>c.data===t.data&&c.hora===t.hora))continue;await put('cultos',novoCulto(t.data,t.hora,t.nome));n++}alert(n+' culto(s) criado(s).');go()};
window.avulso=async()=>{const d=$('#nData').value;if(!d)return;const c=novoCulto(d,$('#nHora').value,$('#nNome').value||'Evento avulso',$('#nPolo').value||cfg.polo);c.avulso=true;c.amb=$('#nAmb').checked;await put('cultos',c);location.hash='#escala/'+d.slice(0,7);go()};
const LIM='2027-01-30';
function calHTML(m,cs){const d0=pd(m+'-01');const n=new Date(d0.getFullYear(),d0.getMonth()+1,0).getDate();const dias=new Set(cfg.modelo.map(t=>t.dia));const hoje=ymd(new Date());let h='';
for(let i=0;i<d0.getDay();i++)h+='<span></span>';
for(let k=1;k<=n;k++){const ds=m+'-'+String(k).padStart(2,'0');const dw=pd(ds).getDay();const cc=cs.filter(c=>c.data===ds);const ev=cc.some(c=>c.avulso);const cu=cc.some(c=>!c.avulso);
const cls=[ev?'cev':'',cu?'ccu':dias.has(dw)?'cmod':'',ds===hoje?'chj':'',ds>LIM?'cfora':''].join(' ');h+=`<button class="${cls}" onclick="tocarDia('${ds}')">${k}${cc.length?`<i>${cc.length}</i>`:''}</button>`}
return`<div class="card cal"><div class="cgrid chead">${['D','S','T','Q','Q','S','S'].map(x=>`<span>${x}</span>`).join('')}</div><div class="cgrid">${h}</div><div class="cleg"><span><i class="lg ccu"></i>Culto escalado</span><span><i class="lg cmod"></i>Dia de culto (modelo)</span><span><i class="lg cev"></i>Evento avulso</span></div></div>`}
window.tocarDia=ds=>{const f=$('#fAvulso');if(!f)return;$('#nData').value=ds;f.scrollIntoView({behavior:'smooth',block:'center'});f.classList.add('pisca');setTimeout(()=>f.classList.remove('pisca'),1200);$('#nNome').focus()};
window.gerarAte=async()=>{let m=mesAtual(),n=0;const todos=await getAll('cultos');while(m<=LIM.slice(0,7)){for(const t of datasModelo(m)){if(t.data>LIM||t.data<ymd(new Date()))continue;if(todos.some(c=>c.kind!=='diaria'&&c.data===t.data&&c.hora===t.hora))continue;await put('cultos',novoCulto(t.data,t.hora,t.nome));n++}m=addMes(m,1)}alert(n+' culto(s) criado(s) até 30/01/2027.');go()};
window.setC=async(id,k,v)=>{const c=await get('cultos',id);c[k]=v;await put('cultos',c);go()};
window.setNB=async(id,n)=>{const c=await get('cultos',id);c.bri=c.bri||[];while(c.bri.length<n)c.bri.push('');c.bri.length=n;await put('cultos',c);go()};
window.setBR=async(id,i,v)=>{const c=await get('cultos',id);c.bri[i]=v;await put('cultos',c);go()};
window.setBC=async(id,i,v)=>{const c=await get('cultos',id);c.bc[i]=v;await put('cultos',c);go()};
